// Persistent reminder scheduler engine.
//
// Pure domain rules live in ../shared/reminders.ts. This module owns ONLY
// database transitions, condition re-evaluation, and transport calls. The
// clock and ntfy transports are injected, so tests never touch the network or
// the real clock. Internal reminder tables are not user backup content.
//
// Two independent topics share one engine and one occurrence table: personal
// reminders (personal transport, generated by ticks, gated by settings and
// waking hours) and attack start/end alerts (attack transport, recorded at API
// write time, never gated). Occurrence keys are dedup tokens, not data.

import { dayKeyStartMs, isValidTimeZone, localDayKey } from '../shared/datetime.ts';
import { baselineFromRow } from './mappers.js';
import { collectSettings } from './snapshot.js';
import {
  PREVENTIVE_INTERVALS, assessExercise, assessLowStock, checkInMissing,
  checkInOccurrenceKey, exerciseOccurrenceKey, isWithinWakingWindow,
  normalizeReminderSettings, preventiveDue, preventiveOccurrenceKey,
  stockOccurrenceKey, transientWindow,
} from '../shared/reminders.ts';

const PREVENTIVE_MEDS = [
  { id: 'emgality', name: 'Emgality' },
  { id: 'botox', name: 'Botox' },
];
const DEFAULT_LOW_STOCK_THRESHOLD = 2;
/** Bounded exponential backoff after a failed fetch or non-2xx response. */
const BACKOFF_MINUTES = [1, 5, 15, 60, 240];
const MAX_PER_TICK = 20;

// ── attack start/end alerts (event-driven, separate topic) ───────────
// Attack alerts are never generated by a tick and never gated by the personal
// reminder master switch, per-type toggles, or waking hours. They are recorded
// at write time and delivered through their own transport.
//
// FRESHNESS RULE (enqueue-time only): an event instant `t` is fresh when
//   now - 60min <= t <= now + 5min
// (both bounds inclusive). This suppresses historical/backfilled entries and
// bulk imports while tolerating delayed client retries and small clock skew.
// Anything older than 60 minutes or more than 5 minutes ahead is ignored.
export const ATTACK_PAST_WINDOW_MS = 60 * 60 * 1000; // 60 minutes
export const ATTACK_FUTURE_WINDOW_MS = 5 * 60 * 1000; // 5 minutes
// Bounded retry: an attack alert still undelivered 24 hours after the event
// instant is dropped through the generic expired-skip path instead of being
// retried forever. Delivery is best-effort near-immediate, so this only bounds
// pathological outages.
export const ATTACK_RETRY_WINDOW_MS = 24 * 60 * 60 * 1000; // 24 hours

const ATTACK_START = 'attack_start';
const ATTACK_END = 'attack_end';
const ATTACK_TYPES = new Set([ATTACK_START, ATTACK_END]);

const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);

export function createReminderEngine({
  db, transport, attackTransport = null, now = () => Date.now(), log = () => {},
} = {}) {
  // At least one topic is required; the other may be null (an attack-only or
  // personal-only engine). Personal rows are left pending (never sent, never
  // skipped) while their transport is absent or the master switch is off,
  // instead of crashing the tick.
  if (typeof transport !== 'function' && typeof attackTransport !== 'function') {
    throw new Error('reminder engine requires a transport');
  }
  const personalTransport = typeof transport === 'function' ? transport : null;
  const attackSend = typeof attackTransport === 'function' ? attackTransport : null;

  let currentTick = null;

  function readSettings() {
    const raw = collectSettings(db);
    const timeZone = typeof raw.timezone === 'string' && isValidTimeZone(raw.timezone)
      ? raw.timezone
      : 'UTC';
    const threshold = Number.isInteger(raw.lowStockThreshold) && raw.lowStockThreshold >= 0
      ? raw.lowStockThreshold
      : DEFAULT_LOW_STOCK_THRESHOLD;
    return {
      reminders: normalizeReminderSettings(raw.reminders),
      timeZone,
      threshold,
      planned: isPlainObject(raw.planned) ? raw.planned : {},
    };
  }

  function buildContext(nowMs, settings) {
    const meds = db.prepare(
      "SELECT med_id, ts FROM meds WHERE med_id IN ('emgality','botox')",
    ).all().map((row) => ({ medId: row.med_id, ts: row.ts }));
    return {
      nowMs,
      settings,
      timeZone: settings.timeZone,
      day: localDayKey(nowMs, settings.timeZone),
      meds,
      dayStates: db.prepare('SELECT day, status FROM day_states').all(),
      workouts: db.prepare('SELECT performed_at, kind FROM workouts').all()
        .map((row) => ({ performedAt: row.performed_at, kind: row.kind })),
      attacks: db.prepare('SELECT start, "end" FROM attacks').all(),
      // Nurtec-only, exactly like GET /api/inventory/nurtec: a Tylenol
      // dose/refill/baseline must never move Nurtec stock (which would raise
      // false low-stock alerts). The inventory route is authoritative for the
      // scoping; keep these three predicates in sync with it.
      stock: {
        baselines: db.prepare(
          "SELECT * FROM stock_baselines WHERE med_id = 'nurtec'",
        ).all().map(baselineFromRow),
        doses: db.prepare(
          "SELECT id, ts, quantity FROM meds WHERE med_id = 'nurtec'",
        ).all(),
        refills: db.prepare(
          "SELECT id, date, quantity FROM refills WHERE med_id = 'nurtec'",
        ).all(),
      },
    };
  }

  // ── low-stock episode state (internal, never exported) ─────────────
  const LOW_STATE_KEY = 'low_stock';

  function readLowState() {
    const row = db.prepare('SELECT value FROM reminder_state WHERE key = ?').get(LOW_STATE_KEY);
    if (!row) return { phase: 'armed', episodeKey: null, episodeStartedAt: null };
    try {
      const value = JSON.parse(row.value);
      if (value && (value.phase === 'armed' || value.phase === 'low')) {
        return {
          phase: value.phase,
          episodeKey: typeof value.episodeKey === 'string' ? value.episodeKey : null,
          episodeStartedAt: typeof value.episodeStartedAt === 'string'
            ? value.episodeStartedAt : null,
        };
      }
    } catch {
      // corrupt internal state: treat as armed; a new low episode re-alerts.
    }
    return { phase: 'armed', episodeKey: null, episodeStartedAt: null };
  }

  function writeLowState(state, nowIso) {
    db.prepare(`INSERT INTO reminder_state (key, value, updated_at) VALUES (?, ?, ?)
      ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`)
      .run(LOW_STATE_KEY, JSON.stringify(state), nowIso);
  }

  // ── occurrence bookkeeping ─────────────────────────────────────────
  const insertOccurrence = db.prepare(`INSERT OR IGNORE INTO reminder_occurrences
    (key, type, med_id, scheduled_at, expires_at, status, attempt, next_attempt_at,
     last_attempt_at, sent_at, last_error_category, last_error_status, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);

  function ensurePending({
    key, type, medId = null, scheduledAt, expiresAt = null, nowIso,
  }) {
    const info = insertOccurrence.run(
      key, type, medId, scheduledAt, expiresAt, 'pending', 0, nowIso,
      null, null, null, null, nowIso, nowIso,
    );
    return info.changes > 0 ? 1 : 0;
  }

  /**
   * Record a skipped occurrence without ever re-sending. If a pending row
   * already exists it is transitioned; if none exists a terminal skipped row
   * is inserted so a later tick cannot resurrect the same occurrence key.
   */
  function recordSkip({
    key, type, medId = null, scheduledAt, expiresAt = null, reason, nowIso,
  }) {
    const updated = db.prepare(`UPDATE reminder_occurrences
      SET status = 'skipped', last_error_category = ?, updated_at = ?
      WHERE key = ? AND status = 'pending'`).run(reason, nowIso, key);
    if (updated.changes > 0) return 1;
    const inserted = insertOccurrence.run(
      key, type, medId, scheduledAt, expiresAt, 'skipped', 0, nowIso,
      null, null, reason, null, nowIso, nowIso,
    );
    return inserted.changes > 0 ? 1 : 0;
  }

  function skipPending(whereSql, params, reason, nowIso) {
    return db.prepare(`UPDATE reminder_occurrences
      SET status = 'skipped', last_error_category = ?, updated_at = ?
      WHERE status = 'pending' ${whereSql}`)
      .run(reason, nowIso, ...params).changes;
  }

  // ── attack start/end occurrences (event-driven, same table) ───────
  // Attack rows reuse the whole occurrence/claim/backoff/skip/recovery
  // machinery. Their keys are dedup tokens ONLY: `attack_start:<attackId>:<raw
  // start>` and `attack_end:<attackId>:<raw end>`. The raw start/end strings
  // are appended for uniqueness and are NEVER parsed back out of the key; the
  // attack id lives in the med_id column and the event instant string lives in
  // scheduled_at. expires_at is `event instant + ATTACK_RETRY_WINDOW_MS`, so an
  // alert still undelivered 24 hours after the event is skipped as expired
  // instead of retried forever (personal preventive/stock rows keep NULL).
  function attackOccurrenceKey(type, attackId, instant) {
    return `${type}:${attackId}:${instant}`;
  }

  /**
   * Epoch ms of a fresh attack instant, or null when the value is not a
   * parseable instant inside the enqueue-time freshness window. Returning the
   * parsed instant avoids re-parsing it for the retry-expiry bound.
   */
  function freshAttackInstantMs(instant, nowMs) {
    if (typeof instant !== 'string' || instant === '') return null;
    const ms = Date.parse(instant);
    if (!Number.isFinite(ms)) return null;
    if (ms < nowMs - ATTACK_PAST_WINDOW_MS || ms > nowMs + ATTACK_FUTURE_WINDOW_MS) {
      return null;
    }
    return ms;
  }

  /**
   * Record attack start/end events for delivery. Synchronous and best-effort:
   * it only inserts rows and never throws to the API caller. No-op when the
   * attack topic is not configured, so a later-enabled topic never receives
   * stale events that were queued while it could not send.
   *
   * START: a genuine insert (before === null) with a fresh, parseable start.
   * END: a null/absent -> non-null `end` transition (including a fresh POST
   * that already carries an end) with a fresh, parseable end. Correcting an
   * existing non-null end to another non-null value enqueues nothing; the
   * stale pending alert is skipped by the send-time relevance check.
   *
   * Each recorded occurrence expires 24 hours after its event instant
   * (ATTACK_RETRY_WINDOW_MS), bounding retries during a long outage.
   */
  function noteAttackWrite({ before = null, after } = {}) {
    if (!attackSend) return;
    try {
      if (!isPlainObject(after)) return;
      const id = typeof after.id === 'string' ? after.id : '';
      if (!id) return;
      const nowMs = now();
      const nowIso = new Date(nowMs).toISOString();
      const isInsert = before === null || before === undefined;

      const startMs = freshAttackInstantMs(after.start, nowMs);
      if (isInsert && startMs !== null) {
        ensurePending({
          key: attackOccurrenceKey(ATTACK_START, id, after.start),
          type: ATTACK_START,
          medId: id,
          scheduledAt: after.start,
          expiresAt: new Date(startMs + ATTACK_RETRY_WINDOW_MS).toISOString(),
          nowIso,
        });
      }

      const beforeEnd = isPlainObject(before) ? before.end : null;
      // An empty-string stored end counts as absent: the API accepts any
      // string end, so `end: ''` is a "no end yet" row that must still alert
      // on its first real end. Only a genuine non-empty end can transition.
      const beforeEndAbsent = beforeEnd === null || beforeEnd === undefined
        || beforeEnd === '';
      const endTransition = (isInsert || beforeEndAbsent)
        && typeof after.end === 'string' && after.end !== '';
      const endMs = endTransition ? freshAttackInstantMs(after.end, nowMs) : null;
      if (endMs !== null) {
        ensurePending({
          key: attackOccurrenceKey(ATTACK_END, id, after.end),
          type: ATTACK_END,
          medId: id,
          scheduledAt: after.end,
          expiresAt: new Date(endMs + ATTACK_RETRY_WINDOW_MS).toISOString(),
          nowIso,
        });
      }
    } catch {
      // Never fail the API write; fixed text only (no ids/timestamps/errors).
      log('attack alert enqueue failed');
    }
  }

  // ── occurrence generation (idempotent, deterministic keys) ────────
  function generate(ctx) {
    const { nowMs, settings, timeZone } = ctx;
    const reminders = settings.reminders;
    const nowIso = new Date(nowMs).toISOString();
    let generated = 0;
    let skipped = 0;

    // Preventive: one persistent occurrence per due episode (med + due day).
    for (const med of PREVENTIVE_MEDS) {
      const due = preventiveDue({
        medId: med.id,
        intervalDays: PREVENTIVE_INTERVALS[med.id],
        meds: ctx.meds,
        planned: settings.planned,
        now: nowMs,
        timeZone,
      });
      const currentKey = due.status === 'due' && due.dueDay
        ? preventiveOccurrenceKey(med.id, due.dueDay)
        : null;
      if (currentKey && reminders.preventive) {
        generated += ensurePending({
          key: currentKey,
          type: 'preventive',
          medId: med.id,
          scheduledAt: new Date(due.dueMs).toISOString(),
          nowIso,
        });
      }
      if (currentKey) {
        skipped += skipPending(
          "AND type = 'preventive' AND med_id = ? AND key <> ?",
          [med.id, currentKey], 'condition_gone', nowIso,
        );
      } else {
        // Not currently due (dose logged / planned moved / no schedule).
        skipped += skipPending(
          "AND type = 'preventive' AND med_id = ?",
          [med.id], 'condition_gone', nowIso,
        );
      }
    }

    // Low Nurtec stock: server-side episode, independent of the browser latch.
    const stock = assessLowStock({
      ...ctx.stock,
      now: nowMs,
      timeZone,
      threshold: settings.threshold,
    });
    let lowState = readLowState();
    if (stock.status === 'known' && !stock.low) {
      if (lowState.phase !== 'armed' || lowState.episodeKey !== null) {
        lowState = { phase: 'armed', episodeKey: null, episodeStartedAt: null };
        writeLowState(lowState, nowIso);
      }
      skipped += skipPending("AND type = 'stock'", [], 'condition_gone', nowIso);
    } else if (stock.status === 'known' && stock.low) {
      if (lowState.phase !== 'low' || !lowState.episodeKey) {
        lowState = {
          phase: 'low',
          episodeKey: nowIso,
          episodeStartedAt: nowIso,
        };
        writeLowState(lowState, nowIso);
      }
      const currentKey = stockOccurrenceKey(lowState.episodeKey);
      if (reminders.lowStock) {
        generated += ensurePending({
          key: currentKey,
          type: 'stock',
          medId: 'nurtec',
          scheduledAt: nowIso,
          nowIso,
        });
      }
      skipped += skipPending(
        "AND type = 'stock' AND key <> ?",
        [currentKey], 'condition_gone', nowIso,
      );
    }
    // Unknown stock: never alert. Existing pending rows are left in place but
    // send-time relevance returns false, so they cannot deliver.

    // Daily check-in: one occurrence per local day; transient grace window.
    if (reminders.checkIn) {
      const window = transientWindow(
        ctx.day, reminders.checkInTime, reminders.graceMinutes, timeZone,
      );
      if (nowMs >= window.scheduledMs) {
        const key = checkInOccurrenceKey(ctx.day);
        const base = {
          key,
          type: 'checkin',
          scheduledAt: window.scheduledAt,
          expiresAt: window.expiresAt,
          nowIso,
        };
        if (!checkInMissing(ctx.dayStates, ctx.day)) {
          skipped += recordSkip({ ...base, reason: 'condition_gone' });
        } else if (nowMs >= window.expiresMs) {
          skipped += recordSkip({ ...base, reason: 'expired' });
        } else {
          generated += ensurePending(base);
        }
      }
    }

    // Exercise: one occurrence per local day while the Sunday-week is behind.
    if (reminders.exercise) {
      const window = transientWindow(
        ctx.day, reminders.exerciseTime, reminders.graceMinutes, timeZone,
      );
      if (nowMs >= window.scheduledMs) {
        const key = exerciseOccurrenceKey(ctx.day);
        const assessment = assessExercise({
          workouts: ctx.workouts,
          dayStates: ctx.dayStates,
          attacks: ctx.attacks,
          day: ctx.day,
          now: nowMs,
          timeZone,
        });
        const base = {
          key,
          type: 'exercise',
          scheduledAt: window.scheduledAt,
          expiresAt: window.expiresAt,
          nowIso,
        };
        if (assessment.suppressed) {
          skipped += recordSkip({ ...base, reason: 'condition_gone' });
        } else if (nowMs >= window.expiresMs) {
          skipped += recordSkip({ ...base, reason: 'expired' });
        } else {
          generated += ensurePending(base);
        }
      }
    }

    return { generated, skipped };
  }

  // ── send-time relevance (conditions can disappear during retries) ──
  function typeEnabled(type, reminders) {
    if (type === 'preventive') return reminders.preventive;
    if (type === 'stock') return reminders.lowStock;
    if (type === 'checkin') return reminders.checkIn;
    if (type === 'exercise') return reminders.exercise;
    return false;
  }

  function occurrenceRelevant(row, ctx) {
    const { settings, timeZone } = ctx;
    const reminders = settings.reminders;
    if (row.type === 'preventive') {
      if (!reminders.preventive || !row.med_id) return false;
      const interval = PREVENTIVE_INTERVALS[row.med_id];
      if (!interval) return false;
      const due = preventiveDue({
        medId: row.med_id,
        intervalDays: interval,
        meds: ctx.meds,
        planned: settings.planned,
        now: ctx.nowMs,
        timeZone,
      });
      return due.status === 'due' && due.dueDay !== null
        && preventiveOccurrenceKey(row.med_id, due.dueDay) === row.key;
    }
    if (row.type === 'stock') {
      if (!reminders.lowStock) return false;
      const state = readLowState();
      if (state.phase !== 'low' || !state.episodeKey) return false;
      if (stockOccurrenceKey(state.episodeKey) !== row.key) return false;
      const stock = assessLowStock({
        ...ctx.stock,
        now: ctx.nowMs,
        timeZone,
        threshold: settings.threshold,
      });
      return stock.status === 'known' && stock.low;
    }
    if (row.type === 'checkin') {
      if (!reminders.checkIn) return false;
      return row.key === checkInOccurrenceKey(ctx.day)
        && checkInMissing(ctx.dayStates, ctx.day);
    }
    if (row.type === 'exercise') {
      if (!reminders.exercise) return false;
      if (row.key !== exerciseOccurrenceKey(ctx.day)) return false;
      const assessment = assessExercise({
        workouts: ctx.workouts,
        dayStates: ctx.dayStates,
        attacks: ctx.attacks,
        day: ctx.day,
        now: ctx.nowMs,
        timeZone,
      });
      return assessment.suppressed === null;
    }
    return false;
  }

  function formatDay(day, timeZone) {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short', day: 'numeric', timeZone,
    }).format(new Date(dayKeyStartMs(day, timeZone)));
  }

  // ── attack relevance and messages ─────────────────────────────────
  function currentAttackRow(attackId) {
    if (typeof attackId !== 'string' || attackId === '') return undefined;
    return db.prepare('SELECT id, start, "end" FROM attacks WHERE id = ?').get(attackId);
  }

  /**
   * Send-time relevance for attack rows: the current attacks row must still
   * exist and its event instant must still equal the stored occurrence
   * instant. A deleted or changed attack therefore never sends a stale or
   * contradictory alert; the pending row is skipped as condition_gone.
   */
  function attackOccurrenceRelevant(row) {
    const current = currentAttackRow(row.med_id);
    if (!current) return false;
    const expected = Date.parse(row.scheduled_at);
    if (!Number.isFinite(expected)) return false;
    if (row.type === ATTACK_START) return Date.parse(current.start) === expected;
    if (row.type === ATTACK_END) return Date.parse(current.end) === expected;
    return false;
  }

  function formatInstant(instant, timeZone) {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric', minute: '2-digit', timeZone,
    }).format(new Date(instant));
  }

  /** Short date with year, e.g. `Oct 25, 2026`, in the settings time zone. */
  function formatEventDay(eventMs, timeZone) {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short', day: 'numeric', year: 'numeric', timeZone,
    }).format(new Date(eventMs));
  }

  /**
   * Whole-minute duration, rounded. Returns null unless both instants parse
   * and end >= start, so a corrected/negative interval never prints a bogus
   * duration. 60+ minutes format as `Xh Ym`, otherwise `Ym`.
   */
  function formatDuration(startInstant, endInstant) {
    const startMs = Date.parse(startInstant);
    const endMs = Date.parse(endInstant);
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) {
      return null;
    }
    const minutes = Math.round((endMs - startMs) / 60000);
    if (minutes >= 60) return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
    return `${minutes}m`;
  }

  /**
   * Attack messages contain ONLY the event time (and, for the end event, a
   * duration when valid). A delayed alert whose event fell on an earlier local
   * day (settings time zone) also carries that date, so it cannot read as a
   * current event. Never pain, medications, notes, symptoms, triggers, aura, or
   * any other health detail.
   */
  function buildAttackMessage(row, ctx) {
    const { timeZone } = ctx;
    const eventMs = Date.parse(row.scheduled_at);
    const at = formatInstant(row.scheduled_at, timeZone);
    // Send-time relevance guarantees a parseable instant matching the current
    // row; the guard only keeps a malformed value from throwing here.
    const dated = Number.isFinite(eventMs) && localDayKey(eventMs, timeZone) !== ctx.day;
    const onDate = dated ? ` on ${formatEventDay(eventMs, timeZone)}` : '';
    if (row.type === ATTACK_START) {
      return { title: 'Attack started', body: `Attack started at ${at}${onDate}.` };
    }
    // Re-read the current row: the duration must reflect the values that just
    // passed the send-time relevance check (start/end may have been corrected).
    const current = currentAttackRow(row.med_id);
    const duration = current ? formatDuration(current.start, current.end) : null;
    return {
      title: 'Attack ended',
      body: `Attack ended at ${at}${onDate}${duration ? ` (${duration})` : ''}.`,
    };
  }

  function buildMessage(row, ctx) {
    const { timeZone, settings } = ctx;
    if (row.type === 'preventive') {
      const med = PREVENTIVE_MEDS.find((m) => m.id === row.med_id);
      const name = med ? med.name : row.med_id;
      const dueDay = row.key.split(':').slice(2).join(':');
      return {
        title: `${name} dose due`,
        body: `Your ${name} dose was due ${formatDay(dueDay, timeZone)}. `
          + 'Log it in the app when you take it.',
      };
    }
    if (row.type === 'stock') {
      const stock = assessLowStock({
        ...ctx.stock,
        now: ctx.nowMs,
        timeZone,
        threshold: settings.threshold,
      });
      const quantity = stock.quantity;
      return {
        title: 'Nurtec stock low',
        body: quantity !== null && quantity < 0
          ? `Recorded Nurtec stock is ${quantity} tablets (negative). Correct it in Settings.`
          : `${quantity} Nurtec tablets left, at or below your ${settings.threshold}-tablet alert level. `
            + 'Log a refill when you pick up more.',
      };
    }
    if (row.type === 'checkin') {
      return {
        title: 'Daily check-in',
        body: 'Log how you feel today: Well, Off, or Attack. One tap is enough.',
      };
    }
    const assessment = assessExercise({
      workouts: ctx.workouts,
      dayStates: ctx.dayStates,
      attacks: ctx.attacks,
      day: ctx.day,
      now: ctx.nowMs,
      timeZone,
    });
    if (assessment.state === 'off') {
      return {
        title: 'Gentle movement option',
        body: "Feeling off today? A 10-minute light walk or mobility counts. Log it when you're done.",
      };
    }
    return {
      title: 'Weekly movement check',
      body: 'Your weekly goals are still open: 2 strength and 3 cardio sessions. '
        + 'A short session still counts.',
    };
  }

  function classifyFailure(error) {
    if (error && typeof error.category === 'string') {
      return {
        category: error.category.slice(0, 40),
        status: Number.isInteger(error.status) ? error.status : null,
      };
    }
    return { category: 'unknown', status: null };
  }

  async function processPending(ctx) {
    const nowMs = ctx.nowMs;
    const nowIso = new Date(nowMs).toISOString();
    // Two per-class selections, each with its own per-tick budget: due but
    // suppressed personal rows (master switch off) can never fill the window
    // and starve attack delivery. Attack rows are processed first, because
    // immediacy is the point of that topic; the personal batch keeps the same
    // `scheduled_at, key` order and the same MAX_PER_TICK bound as before.
    const attackRows = db.prepare(`SELECT * FROM reminder_occurrences
      WHERE status = 'pending' AND next_attempt_at <= ?
        AND type IN ('attack_start', 'attack_end')
      ORDER BY scheduled_at, key LIMIT ?`).all(nowIso, MAX_PER_TICK);
    const personalRows = db.prepare(`SELECT * FROM reminder_occurrences
      WHERE status = 'pending' AND next_attempt_at <= ?
        AND type NOT IN ('attack_start', 'attack_end')
      ORDER BY scheduled_at, key LIMIT ?`).all(nowIso, MAX_PER_TICK);
    const rows = [...attackRows, ...personalRows];
    let sent = 0;
    let failed = 0;
    let skipped = 0;

    for (const row of rows) {
      const isAttack = ATTACK_TYPES.has(row.type);
      // Non-attack rows are suppressed (left pending, never sent, never
      // skipped or expired) while the personal master switch is off or the
      // personal topic is absent. This check precedes the expiry check on
      // purpose: a disabled master switch must not burn transient rows.
      // Attack rows ignore the personal master switch entirely.
      if (!isAttack && (!personalTransport || !ctx.settings.reminders.enabled)) {
        continue;
      }
      // Generic expiry, shared by transient personal rows past their grace
      // window and attack rows past ATTACK_RETRY_WINDOW_MS.
      if (row.expires_at && nowIso >= row.expires_at) {
        skipped += recordSkip({
          key: row.key,
          type: row.type,
          medId: row.med_id,
          scheduledAt: row.scheduled_at,
          expiresAt: row.expires_at,
          reason: 'expired',
          nowIso,
        });
        continue;
      }
      if (isAttack) {
        // Attack alerts bypass the personal master switch, per-type toggles,
        // and waking hours. Without an attack topic they are suppressed: left
        // pending until the 24h retry window expires, never burned eagerly.
        if (!attackSend) continue;
        if (!attackOccurrenceRelevant(row)) {
          skipped += skipPending('AND key = ?', [row.key], 'condition_gone', nowIso);
          continue;
        }
      } else {
        // The suppression guard above already returned unless a personal
        // transport exists and the master switch is on.
        if (!typeEnabled(row.type, ctx.settings.reminders)) {
          // Disabled per-type reminders are suppressed, not burned: a pending
          // persistent condition resumes when the user re-enables it.
          continue;
        }
        if (!occurrenceRelevant(row, ctx)) {
          skipped += skipPending(
            'AND key = ?', [row.key], 'condition_gone', nowIso,
          );
          continue;
        }
        // Persistent conditions wait for the next waking window; transient rows
        // were already skipped above once their grace period elapsed.
        if (!isWithinWakingWindow(nowMs, ctx.settings.reminders, ctx.timeZone)) continue;
      }

      const claim = db.prepare(`UPDATE reminder_occurrences
        SET status = 'sending', attempt = attempt + 1, last_attempt_at = ?, updated_at = ?
        WHERE key = ? AND status = 'pending'`).run(nowIso, nowIso, row.key);
      if (!claim.changes) continue;

      const attempt = row.attempt + 1;
      try {
        const message = isAttack ? buildAttackMessage(row, ctx) : buildMessage(row, ctx);
        await (isAttack ? attackSend : personalTransport)(message);
        db.prepare(`UPDATE reminder_occurrences
          SET status = 'succeeded', sent_at = ?, next_attempt_at = ?,
              last_error_category = NULL, last_error_status = NULL, updated_at = ?
          WHERE key = ? AND status = 'sending'`)
          .run(nowIso, nowIso, nowIso, row.key);
        sent += 1;
      } catch (error) {
        const { category, status } = classifyFailure(error);
        const delayMinutes = BACKOFF_MINUTES[
          Math.min(attempt - 1, BACKOFF_MINUTES.length - 1)
        ];
        const nextIso = new Date(nowMs + delayMinutes * 60000).toISOString();
        db.prepare(`UPDATE reminder_occurrences
          SET status = 'pending', next_attempt_at = ?, last_error_category = ?,
              last_error_status = ?, updated_at = ?
          WHERE key = ? AND status = 'sending'`)
          .run(nextIso, category, status, nowIso, row.key);
        failed += 1;
        // Category only; never an error message/URL/token/response body.
        log(`reminder delivery failed (${category})`);
      }
    }
    return { sent, failed, skipped };
  }

  async function runTick() {
    const nowMs = now();
    const settings = readSettings();
    if (!settings.reminders.enabled) {
      if (!attackSend) {
        return { disabled: true, generated: 0, sent: 0, failed: 0, skipped: 0 };
      }
      // Attack alerts bypass the personal master switch. They are event-driven
      // (recorded by noteAttackWrite, never generated here), so a tick only
      // delivers pending attack occurrences.
      const ctx = buildContext(nowMs, settings);
      const delivery = await processPending(ctx);
      return {
        disabled: false,
        generated: 0,
        sent: delivery.sent,
        failed: delivery.failed,
        skipped: delivery.skipped,
      };
    }
    const ctx = buildContext(nowMs, settings);
    // No personal topic (attack-only deployment): personal occurrences could
    // never be delivered, so none are generated. Personal conditions simply
    // regenerate on the first tick after a personal topic is configured.
    const generated = personalTransport ? generate(ctx) : { generated: 0, skipped: 0 };
    const delivery = await processPending(ctx);
    return {
      disabled: false,
      generated: generated.generated,
      sent: delivery.sent,
      failed: delivery.failed,
      skipped: generated.skipped + delivery.skipped,
    };
  }

  /**
   * Startup recovery for a process that died mid-send. The status was already
   * 'sending' (at-most-once transition); requeueing can duplicate a message
   * only if the HTTP request was accepted but the success write never ran.
   * This crash-around-send tradeoff is documented as a remaining risk.
   */
  function recoverInterrupted() {
    const nowIso = new Date(now()).toISOString();
    return db.prepare(`UPDATE reminder_occurrences
      SET status = 'pending', next_attempt_at = ?, updated_at = ?
      WHERE status = 'sending'`).run(nowIso, nowIso).changes;
  }

  function tick() {
    if (currentTick) return currentTick;
    currentTick = runTick().finally(() => {
      currentTick = null;
    });
    return currentTick;
  }

  return { tick, recoverInterrupted, noteAttackWrite };
}
